CREATE TABLE IF NOT EXISTS "kist" (
    "KistId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "OrganizationId" bigint NOT NULL,
    "VoucherId" bigint NOT NULL,
