CREATE TABLE IF NOT EXISTS "ledger" (
    "LedgerId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "OrganizationId" bigint NOT NULL DEFAULT '0',
    "ParentLedgerId" bigint NOT NULL DEFAULT '0',
    "LedgerName" varchar(80) NOT NULL,
    "RealName" varchar(50) NOT NULL DEFAULT '',
    "GroupId" integer NOT NULL,
    "AgentLedgerId" bigint NOT NULL,
    "LimitType" varchar(3) NOT NULL CHECK ("LimitType" IN ('NO', 'YES')),
    "DaraRate" double precision DEFAULT '0',
    "DaraCommission" double precision DEFAULT '0',
    "AkharRate" double precision DEFAULT '0',
    "AkharCommission" double precision DEFAULT '0',
    "Vapsi" double precision NOT NULL,
    "TPVapsi" varchar(3) NOT NULL CHECK ("TPVapsi" IN ('NO', 'YES')),
    "TPCommission" varchar(3) NOT NULL CHECK ("TPCommission" IN ('No', 'YES')),
    "IsHissa" varchar(3) NOT NULL CHECK ("IsHissa" IN ('NO', 'YES')),
    "IsDibba" varchar(3) NOT NULL CHECK ("IsDibba" IN ('NO', 'YES')),
    "DibbaAmount" double precision NOT NULL,
    "RefLedgerId" bigint NOT NULL DEFAULT '0',
    "HPLedgerId" bigint NOT NULL DEFAULT '0',
    "Grantor" varchar(50) NOT NULL DEFAULT '',
    "DealingType" varchar(7) DEFAULT 'DAILY' CHECK ("DealingType" IN ('DAILY', 'MONTHLY', '25K', '50K', '1L', '2K')),
    "IsReport" varchar(1) NOT NULL CHECK ("IsReport" IN ('1', '0')),
    "TransactionMode" smallint NOT NULL,
    "AccountStatus" varchar(1) NOT NULL CHECK ("AccountStatus" IN ('1', '0')),
    "IsHide" varchar(1) NOT NULL DEFAULT '0' CHECK ("IsHide" IN ('0', '1')),
    "ChatGroupId" bigint DEFAULT '0',
    "TransactionCappingAmount" double precision DEFAULT '0',
    "IsApplyLedgerConfigOnTransaction" integer DEFAULT '0',
    "IsRisky" smallint DEFAULT '1',
    "TransactionLock" integer DEFAULT '0',
    "IsTransactionAllow" smallint DEFAULT '0',
    "RecordStatus" char(1) NOT NULL,
    "AddedBy" varchar(30) NOT NULL,
    "AddedDate" timestamp NOT NULL,
    "UpdatedBy" varchar(30) NOT NULL,
    "UpdatedDate" timestamp NOT NULL,
    PRIMARY KEY ("LedgerId")
);

