CREATE TABLE IF NOT EXISTS "organization" (
    "OrganizationId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "OrganizationOwnerName" varchar(30) NOT NULL,
    "OrganizationName" varchar(30) NOT NULL,
    "OrganizationLogoColor" varchar(20) NOT NULL,
    "OrganizationTheme" varchar(20) NOT NULL,
    "OrganizationThemeDesign" integer DEFAULT '0',
    "OrganizationAppAccess" integer DEFAULT '0',
    "OrganizationMobile" varchar(10) NOT NULL,
    "OrganizationAddress" varchar(60) NOT NULL,
    "OrganizationOnDomain" integer NOT NULL DEFAULT '0',
    "OrganizationDomainURL" varchar(100) NOT NULL DEFAULT '',
    "OrganizationSms" varchar(1) NOT NULL CHECK ("OrganizationSms" IN ('1', '0')),
    "OrganizationSmsUrl" varchar(100) NOT NULL,
    "OrganizationSmsUsername" varchar(30) NOT NULL,
    "OrganizationSmsPassword" varchar(30) NOT NULL,
    "OrganizationSmsPort" varchar(10) NOT NULL,
    "OrganizationSmsSenderId" varchar(10) NOT NULL,
    "OrganizationSmsToken" text NOT NULL,
    "IsTransactionEnable" varchar(1) NOT NULL CHECK ("IsTransactionEnable" IN ('1', '0')),
    "IsEnableTazzaPatti" integer NOT NULL DEFAULT '0',
    "IsMainJantriRoundOf" integer DEFAULT '0',
    "IsCollectionJantriRoundOf" integer DEFAULT '0',
    "IsMultiplyUpMainJantri" integer DEFAULT '0',
    "IsMultiplyUpCollection" integer DEFAULT '0',
    "RoundOffOnMainJantri" integer DEFAULT '50',
    "RoundOffOnCollection" integer DEFAULT '50',
    "skey_Random_Old" integer NOT NULL DEFAULT '1',
    "skey_Crossing" integer NOT NULL DEFAULT '1',
    "skey_FromTo" integer NOT NULL DEFAULT '1',
    "skey_Random_New" integer NOT NULL DEFAULT '1',
    "skey_OddEven" integer NOT NULL DEFAULT '0',
    "skey_EkdiDukdi" integer NOT NULL DEFAULT '0',
    "skey_Joda" integer NOT NULL DEFAULT '0',
    "skey_JodiDaane" integer DEFAULT '0',
    "IsVoucherVerify" smallint DEFAULT '0',
    "IsDashboardStaffGainerLooser" smallint DEFAULT '0',
    "IsAutoSalaryCreate" smallint DEFAULT '0',
    "IsAutoSalaryPaid" smallint DEFAULT '0',
    "IsTransactionAlreadyExist" smallint DEFAULT '0',
    "HissaNotApplyMode" integer DEFAULT '0',
    "VapsiWorkingDays" integer DEFAULT '0',
    "IsAutoUserNameForStaff" integer DEFAULT '0',
    "UnPaidKistLastDateOfProcess" date DEFAULT '1970-01-01',
    "UnPaidKistPopupForDashboard" integer DEFAULT '0',
    "IsBackLimitPopup" smallint DEFAULT '0',
    "AbsentLedgerLockDays" integer DEFAULT '0',
    "TelegramAllow" smallint DEFAULT '0',
    "TelegramUrl" varchar(250) DEFAULT '',
    "TelegramSession" text,
    "OrganizationStartDate" date NOT NULL,
    "OrganizationEndDate" date NOT NULL,
    "IsOrganizationAllow" varchar(1) NOT NULL CHECK ("IsOrganizationAllow" IN ('1', '0')),
    "RecordStatus" char(1) NOT NULL,
    "AddedBy" varchar(30) NOT NULL,
    "AddedDate" timestamp NOT NULL,
    "UpdatedBy" varchar(30) NOT NULL,
    "UpdatedDate" timestamp NOT NULL,
    PRIMARY KEY ("OrganizationId")
);

